{
  "candidates": [
    {
      "explanation": "Moderate pipeline-aware relaxation: reduce orders when pipeline is high relative to recent demand, but keep some buffer for backlog. Node0 reduces most due to high backlog and pipeline; Node1 reduces moderately; Node2 reduces slightly.",
      "rules": [
        {
          "when": "agent==0 and pipeline>recent*3",
          "delta": "-3"
        },
        {
          "when": "agent==0 and backlog>20",
          "delta": "-2"
        },
        {
          "when": "agent==1 and pipeline>recent*3",
          "delta": "-2"
        },
        {
          "when": "agent==2 and pipeline>recent*3",
          "delta": "-1"
        }
      ]
    },
    {
      "explanation": "Stronger pipeline-aware relaxation: cut orders more aggressively when pipeline exceeds 3x recent demand, especially upstream. Also reduce if backlog is high to avoid over-ordering.",
      "rules": [
        {
          "when": "agent==0 and pipeline>recent*3",
          "delta": "-4"
        },
        {
          "when": "agent==0 and backlog>20",
          "delta": "-3"
        },
        {
          "when": "agent==1 and pipeline>recent*3",
          "delta": "-3"
        },
        {
          "when": "agent==2 and pipeline>recent*3",
          "delta": "-2"
        }
      ]
    },
    {
      "explanation": "Coordinated relaxation with growth consideration: reduce orders when pipeline is high and growth is moderate, but allow slight increase if growth is very high and backlog is low to avoid starving downstream.",
      "rules": [
        {
          "when": "agent==0 and pipeline>recent*3 and growth<2",
          "delta": "-3"
        },
        {
          "when": "agent==0 and backlog>20",
          "delta": "-2"
        },
        {
          "when": "agent==1 and pipeline>recent*3",
          "delta": "-2"
        },
        {
          "when": "agent==2 and pipeline>recent*3",
          "delta": "-1"
        }
      ]
    }
  ]
}

{
  "candidates": [
    {
      "explanation": "Pipeline-aware relaxation: reduce orders when pipeline is high relative to recent demand, increase when backlog is high and pipeline low. Node-specific thresholds.",
      "rules": [
        {
          "when": "agent==0 and backlog>0 and pipeline<10",
          "delta": "min(6, backlog)"
        },
        {
          "when": "agent==0 and pipeline>15",
          "delta": "-2"
        },
        {
          "when": "agent==1 and backlog>0 and pipeline<15",
          "delta": "min(6, backlog)"
        },
        {
          "when": "agent==1 and pipeline>25",
          "delta": "-3"
        }
      ]
    },
    {
      "explanation": "Coordinated correction: boost upstream orders when downstream backlog exists to prevent starvation, but cap increases when pipeline is already large.",
      "rules": [
        {
          "when": "agent==0 and backlog>0",
          "delta": "min(4, backlog)"
        },
        {
          "when": "agent==1 and backlog>0 and pipeline<20",
          "delta": "min(5, backlog)"
        },
        {
          "when": "agent==2 and backlog>0 and pipeline<30",
          "delta": "min(6, backlog)"
        },
        {
          "when": "agent==2 and pipeline>40",
          "delta": "-4"
        }
      ]
    },
    {
      "explanation": "Demand-emergency response: if recent demand exceeds baseline, increase orders to build buffer; otherwise, reduce orders to avoid excess inventory.",
      "rules": [
        {
          "when": "growth>1.1 and backlog>0",
          "delta": "min(6, backlog)"
        },
        {
          "when": "growth>1.1 and backlog==0",
          "delta": "2"
        },
        {
          "when": "growth<0.9 and pipeline>20",
          "delta": "-3"
        },
        {
          "when": "growth<0.9 and pipeline<=20",
          "delta": "-1"
        }
      ]
    }
  ]
}

{
  "candidates": [
    {
      "explanation": "Detects demand surge via growth>1.2 and raises orders at all nodes, with larger increases upstream to prevent pipeline starvation. Uses pipeline and backlog to avoid over-ordering when already sufficient.",
      "rules": [
        {
          "when": "growth > 1.2 and backlog > 0",
          "delta": "min(6, max(2, backlog + 2 - pipeline))"
        },
        {
          "when": "growth > 1.2 and inventory < 10",
          "delta": "min(6, max(1, 3 - pipeline))"
        },
        {
          "when": "growth > 1.2",
          "delta": "min(4, max(1, 2 - pipeline))"
        }
      ]
    },
    {
      "explanation": "Pipeline-aware relaxation: reduces orders when pipeline is high relative to recent demand, preventing upstream backlog. Increases orders when pipeline is low and inventory is low, ensuring downstream service.",
      "rules": [
        {
          "when": "pipeline > recent * 2 and backlog == 0",
          "delta": "-min(4, max(1, pipeline - recent * 2))"
        },
        {
          "when": "pipeline < recent and inventory < 5",
          "delta": "min(4, max(1, recent - pipeline))"
        },
        {
          "when": "backlog > 0",
          "delta": "min(3, backlog)"
        }
      ]
    },
    {
      "explanation": "Coordinated response: node0 increases orders to meet demand, node1 and node2 increase orders to replenish pipelines and prevent future stockouts. Uses growth and inventory to scale corrections.",
      "rules": [
        {
          "when": "agent == 0 and growth > 1.1",
          "delta": "min(5, max(1, 2 - pipeline + backlog))"
        },
        {
          "when": "agent == 1 and growth > 1.1 and inventory < 20",
          "delta": "min(4, max(1, 3 - pipeline))"
        },
        {
          "when": "agent == 2 and growth > 1.1 and inventory < 30",
          "delta": "min(3, max(1, 2 - pipeline))"
        }
      ]
    }
  ]
}

{
  "candidates": [
    {
      "explanation": "Node0 has large backlog and low inventory; increase its order to replenish pipeline. Node1 has inventory and no backlog; keep order steady to avoid upstream backlog. Node2 has inventory and pipeline; reduce order to prevent excess inventory.",
      "rules": [
        {
          "when": "agent==0 and backlog>0",
          "delta": "min(6, backlog/20)"
        },
        {
          "when": "agent==1 and backlog==0 and inventory>0",
          "delta": "0"
        },
        {
          "when": "agent==2 and inventory>0 and pipeline>0",
          "delta": "-2"
        }
      ]
    },
    {
      "explanation": "Node0 backlog is critical; increase order significantly. Node1 has inventory and no backlog; slightly increase order to support downstream. Node2 has inventory and pipeline; reduce order to avoid overstock.",
      "rules": [
        {
          "when": "agent==0 and backlog>0",
          "delta": "min(6, backlog/10)"
        },
        {
          "when": "agent==1 and backlog==0 and inventory>0",
          "delta": "1"
        },
        {
          "when": "agent==2 and inventory>0 and pipeline>0",
          "delta": "-3"
        }
      ]
    },
    {
      "explanation": "Node0 backlog is high; increase order to maximum. Node1 has inventory and no backlog; keep order steady. Node2 has inventory and pipeline; reduce order to prevent excess inventory.",
      "rules": [
        {
          "when": "agent==0 and backlog>0",
          "delta": "6"
        },
        {
          "when": "agent==1 and backlog==0 and inventory>0",
          "delta": "0"
        },
        {
          "when": "agent==2 and inventory>0 and pipeline>0",
          "delta": "-2"
        }
      ]
    }
  ]
}
